void point2TexturedQuad( geometryInS inputs[1], int normalDir, bool orthographic, float2 screenSize, float2 quadPosition[4], 
    float4x4 viewProjInverse, float4x4 projection, inout TriangleStream<geometryInS> outStream ) 
{ 
    geometryInS outS = inputs[0]; 
    if(normalDir < 1) outS.Nw = float3(0.0f, 0.0f, 0.0f); 
    float2 halfPixel = float2( 0.5f, 0.5f ); 
    float2 scale = 4 * outS.radius * screenSize.x / screenSize.xy; 
	 if(orthographic) scale *= 0.5 * projection[0][0]; 

    [unroll] for( int i = 0; i < 4; ++i ) 
    { 
        float4 quad = float4(scale * quadPosition[i], 0.0, 0.0); 
        outS.Pc = inputs[0].Pc + quad; 
        outS.Pw = inputs[0].Pw + mul(quad, viewProjInverse).xyz; 
        outS.uvCoord = quadPosition[i] + halfPixel; 
        outStream.Append( outS ); 
    } 
    outStream.RestartStrip(); 
}


void point2TexturedQuad( AttribArray<geometryInS> inputs, 
    int normalDir, bool orthographic, float2 screenSize, float2 quadPosition[4], 
    float4x4 viewProjInverse, float4x4 projection ) 
{ 

    geometryInS outS = inputs[0]; 
    if(normalDir < 1) outS.Nw = float3(0.0f, 0.0f, 0.0f); 
    float2 halfPixel = float2( 0.5f, 0.5f ); 
    float2 scale = 4 * outS.radius * screenSize.x / screenSize.xy; 
	 if(orthographic) scale *= 0.5 * projection[0][0]; 

    for( int i = 0; i < 4; ++i ) 
    { 
        float4 quad = float4(scale * quadPosition[i], 0.0, 0.0); 
        outS.Pc = inputs[0].Pc + quad; 
        outS.Pw = inputs[0].Pw + mul(viewProjInverse, quad).xyz; 
        outS.uvCoord = quadPosition[i] + halfPixel; 
        emitVertex( outS ); 
    } 
    restartStrip(); 
}


void point2TexturedQuad(  
    int normalDir, bool orthographic, vec2 screenSize, vec2 quadPosition[4], 
    mat4x4 viewProjInverse, mat4x4 projection ) 
{ 

    GEO_OUT_struct outS = copyFromGEO_IN(0); 
    if(normalDir < 1) outS.Nw = vec3(0.0f, 0.0f, 0.0f); 
    vec2 halfPixel = vec2( 0.5f, 0.5f ); 
    vec2 scale = 4 * outS.radius * screenSize.x / screenSize.xy; 
	 if(orthographic) scale *= 0.5 * projection[0][0]; 

    for( int i = 0; i < 4; ++i ) 
    { 
        vec4 quad = vec4(scale * quadPosition[i], 0.0, 0.0); 
        outS.Pc = gl_in[0].gl_Position + quad; 
        outS.Pw = GEO_IN[0].Pw + mul(viewProjInverse, quad).xyz; 
        outS.uvCoord = quadPosition[i] + halfPixel; 
        EmitGeoStruct( outS ); 
    } 
    EndPrimitive(); 
}


