    float4x4 viewProjInverse, float4x4 projection, inout TriangleStream<geometryInS> outStream ) 
{ 
    geometryInS outS = inputs[0]; 
    if(normalDir < 1) outS.Nw = float3(0.0f, 0.0f, 0.0f); 
    float2 halfPixel = float2( 0.5f, 0.5f ); 
    float2 scale = 4 * outS.radius * screenSize.x / screenSize.xy; 
	 if(orthographic) scale *= 0.5 * projection[0][0]; 

    [unroll] for( int i = 0; i < 4; ++i ) 
    { 
        float4 quad = float4(scale * quadPosition[i], 0.0, 0.0); 
        outS.Pc = inputs[0].Pc + quad; 
        outS.Pw = inputs[0].Pw + mul(quad, viewProjInverse).xyz; 
        outS.uvCoord = quadPosition[i] + halfPixel; 
        outStream.Append( outS ); 
    } 
    outStream.RestartStrip(); 
}
